def walk(n, steps, texts=(), extent=1000, **kw):
    """Paint a fresh labelled list of n entries, then wheel down steps rows."""
    m = Machine()
    w, es = m.page_list(n, extent=extent, **kw)
    m.label(es, texts)
    m.paint(w)
    for _ in range(steps):
        assert m.call() == 11
    assert m.selected(w) == steps
    return (m, w, es)
