        assert self.get(gp - 22596) == syms['widget_on'] and self.get(gp - 22560) == syms['on_common_keyup'] == 5186452
        self.nodes[self.top].setdefault('handlers', []).append((O['EVT_KEY_UP'], 5186452, self.top))
