def cpm_wheel(m, key, n=1):
    for _ in range(n):
        m.call(key)
        m.stack_rows()
    m.paint(m.view)

def cpm_centre(m):
    m.confirm()
    m.advance(0, clear=False)
    m.stack_rows()
    m.paint(m.view)
