def vol_closed(q):
    q.nodes[q.wm]['children'] = [q.win]
    q.top = q.win
    q.calls = []
    q.advance(O['VOL_POLL_MS'])
    assert not q.timers and [q.nodes[w]['visible'] for w in (q.elapsed, q.remain)] == [1, 1]

