def tap_line(m, y=160, dy=0, abort=False, ms=0, dx=0):
    m.calls = []
    m.touch('EVT_POINTER_DOWN', 150, y)
    m.pressed = 1
    loop(m)
    if abort:
        m.touch('EVT_POINTER_ABORT', 150 + dx, y + dy)
    if ms:
        m.advance(ms, clear=False)
    m.touch('EVT_POINTER_UP_BEFORE', 150 + dx, y + dy)
    m.pressed = 0
    loop(m)
    return moves(m)

