def track(m, name, path, disc=0, no=0, cue=0):
    r = m.song(name)
    m.word(r + O['REC_PATH'], m.string(path))
    for k, v in (('REC_DISC', disc), ('REC_TRACK', no), ('REC_CUE_START', cue)):
        m.word(r + O[k], v)
    return r
