def fitted(px, w, h):
    side = max(w, h)
    out = []
    for y in range(160):
        sy = y * side // 160 - (side - h) // 2
        for x in range(160):
            sx = x * side // 160 - (side - w) // 2
            out.append(px[(sy * w + sx) * 4:(sy * w + sx) * 4 + 4] if 0 <= sx < w and 0 <= sy < h else struct.pack('<I', 4278190080))
    return b''.join(out)
