def font_row(setup, text):
    k = Machine()
    if setup:
        setup(k)
    w = k.page('artistinfo_page', 'scroll_view')
    k.word(w + O['W_PARENT'], k.top)
    k.word(k.top + O['W_PARENT'], k.wm)
    k.nodes[w]['name'] = 'scroll_view_track'
    k.row_record = k.alloc(128)
    for off in (8, 12, 16, 24):
        k.word(k.row_record + off, k.string(text))
    k.word(k.row_record + 72, 1)
    k.mock('button_create', 'list_item_create', 'image_create', 'view_create', 'hscroll_label_create', 'gif_image_create', 'widget_use_style', 'widget_set_name', 'widget_set_text_utf8', 'widget_set_visible', 'widget_on', 'widget_destroy_children', 'image_set_draw_type', 'image_base_set_image', 'set_hscroll_label_attribute', 'hscroll_label_set_only_focus', 'hscroll_label_set_ellipses', 'hscroll_label_set_speed', 'gif_image_play', 'deque_at', 'deque_size', 'tk_snprintf', 'batch_get_selectitem', 'file_is_playing', 'getFormatString', 'getMusicByPlayList', 'get_albumcover_listsize', 'mclGetPlayStatus', 'list_get_img_pic', 'strcmp@GLIBC_2.0', 'toolsTrimLeft', 'toolsTrimRight')
    k.handlers[4902944] = 'row_toolbar'
    assert k.call(address=4882244, args=(w, 0, 0, 0)) == 0
    button, = [n for n, v in k.nodes.items() if v['type'] == 'button']
    native_row_layout(k, button)
    kids = k.nodes[button]['children']
    text = next((c for c in kids if k.nodes[c]['type'] == 'hscroll_label' or any((k.nodes[t]['type'] == 'hscroll_label' for t in k.nodes[c]['children']))))
    return (k, button, next((c for c in k.nodes[text]['children'] if k.nodes[c]['type'] == 'hscroll_label'), text))
