def routed(m, status=3, way=0, po=0, bal=0):
    """Key Tone's routing (ringnav_buzzer): the stock leaves run on these play status, output way and jacks."""
    for n in ('mclGetPlayStatus', 'mclGetOutputWay'):
        m.handlers.pop(syms[n], None)
    m.word(PLAY_STATUS, status)
    m.word(OUTPUT_WAY, way)
    m.byte(syms['g_po_status'], po)
    m.byte(syms['g_bal_status'], bal)
    return m

def clicker(value=None, tone=1, **kw):
    m = Machine()
    if value is not None:
        m.config['CLICKER'] = value
    m.mock('send@GLIBC_2.0')
    return routed(audible(m, tone=tone), **kw)

def sent(m):
    return [m.text(c[2]) for c in m.calls if c[0] == 'send@GLIBC_2.0']
