def stock(keys, **flags):
    s = audible(Machine(patched=False))
    for flag, value in flags.items():
        s.byte(syms[flag], value)
    out = []
    for key in keys:
        out.append(press(s, key))
        s.call(key, address=HOOKS['on_wm_keyup_before_fun'][0], gap=0, debounce=True)
    return out
