def home_settings(full):
    CONFIG['SHORTCUT'] = '0'
    CONFIG['HOME'] = str(full)
    m = ShuffleMachine()
    del CONFIG['SHORTCUT']
    del CONFIG['HOME']
    m.rockbox_mode = 0
    view, imgs = home_list(m)
    assert m.call(address=home_hook[0], args=(m.top, 0, 0, 0), gap=0) == 0
    btn = named(m, m.top, 'btn_rockbox')
    order = lambda: [m.nodes[r]['name'][4:] for r in m.nodes[view]['children']]
    assert order() == ['playing', 'localmusic', 'coverflow', 'folder', 'shuffle_songs', 'stream', 'home_search', 'settings', 'rockbox'] and (not m.nodes[btn]['visible'])
    assert m.nodes[btn]['sensitive'] == 0
    m.rockbox_mode = 33261
    m.call(address=payload_syms['coverflow_home_layout'], args=(0, 0, 0, 0), gap=0)
    assert order() == HOME_ROWS and m.nodes[btn]['visible'] and (m.nodes[btn]['sensitive'] == 1)
    passed()
    assert m.handler(named(m, m.top, 'img_rockbox'), O['EVT_CLICK'])[0] == payload_syms['home_shortcut_open']
    m.mock('widget_animator_prop_create', 'widget_animator_prop_set_params', 'widget_animator_start')
    lst, sets, art = (named(m, m.top, n) for n in ('list_view_home', 'list_view_homeset', 'img_homeart'))
    sview = named(m, m.top, 'scroll_view_homeset')
    assert not m.nodes[sets]['visible']
    assert m.get(lst + O['W_Y']) == m.get(sets + O['W_Y']) == OLT['home_top']
    assert m.nodes[sets].get('sensitive') == 0
    for img in (named(m, m.top, 'img_playset'), named(m, m.top, 'img_sysset')):
        click_target(m, img)
    m.paint(view)
    for _ in range(6):
        m.call()
    assert m.selected(view) == 6
    m.calls = []
    f, ctx = m.handler(named(m, m.top, 'img_settings'), O['EVT_CLICK'])
    assert m.call(address=f, args=(ctx, m.event, 0, 0), gap=0) == 0
    assert m.nodes[sets]['visible'] and (not m.nodes[lst]['visible']) and (not m.nodes[art]['visible']) and (m.nodes[sets]['animated'] == 'x')
    assert m.nodes[sets]['sensitive'] == 1 and m.nodes[lst]['sensitive'] == 0
    assert [c[1:3] for c in m.calls if c[0] == 'widget_move_resize'][:1] == [(sets, 375)]
    passed()
    assert next((c[2] for c in m.calls if c[0] == 'widget_animator_prop_create')) == O['PAGE_SLIDE_MS'] == 120
    m.advance(119)
    assert signed(m.get(sets + O['W_X'])) > 0
    m.advance(1)
    assert m.get(sets + O['W_X']) == 0 and (not m.props)
    m.paint(sview)
    assert m.selected(sview) == 0 and m.call() == 11 and (m.selected(sview) == 1)
    passed()
    m.calls = []
    assert m.call(O['KEY_RETURN']) == 11
    assert m.nodes[lst]['visible'] and (not m.nodes[sets]['visible']) and (m.nodes[lst]['animated'] == 'x')
    assert m.nodes[lst]['sensitive'] == 1 and m.nodes[sets]['sensitive'] == 0
    assert [c[1:3] for c in m.calls if c[0] == 'widget_move_resize'][:1] == [(lst, -(375 if full else O['HOME_SPLIT_W']) & 4294967295)]
    assert next((c[2] for c in m.calls if c[0] == 'widget_animator_prop_create')) == 120
    m.advance(120)
    assert m.get(lst + O['W_X']) == 0 and (not m.props)
    m.paint(view)
    assert m.selected(view) == 6
    passed()
    m.calls = []
    assert m.call(O['KEY_RETURN']) == 11 and m.selected(view) == 0 and (not destinations(m))
    m.calls = []
    assert m.call(O['KEY_RETURN']) == 11 and m.selected(view) == 0
    dest = destinations(m)
    assert len(dest) == 1 and m.text(dest[0][1]) == 'playing_page'
    assert [m.get(dest[0][2] + 4 * i) for i in range(4)] == [0, 0, 255, 2]
    assert not any((c[0] == 'player_start' for c in m.calls))
    passed()

def home_back(full):
    CONFIG['HOME'] = str(full)
    m = NavigationMachine()
    del CONFIG['HOME']
    view, imgs = home_list(m)
    home = m.top
    m.order = [home]
    m.sync_order()
    m.paint(view)
    assert m.call(O['KEY_RETURN']) == 11 and m.nodes[m.top]['name'] == 'playing_page'
    assert not any((c[0] == 'player_start' for c in m.calls))
    m.call(O['KEY_RETURN'], address=5495388, args=(m.top, m.event, 0, 0), gap=0)
    assert m.top == home
    passed()
    for flag, value in GATES + [(None, 1)]:
        m = Machine()
        view, imgs = home_list(m)
        m.paint(view)
        if flag:
            m.byte(syms[flag], value)
        else:
            m.animating = value
        m.call(O['KEY_RETURN'])
        assert not destinations(m), flag
    m = long_machine()
    view, imgs = home_list(m)
    m.paint(view)
    long_return(m)
    m.call(O['KEY_RETURN'], gap=0)
    assert not destinations(m)
    passed()

def home_carousel():
    CONFIG.update(HOME='2', SHORTCUT='5')
    m = ShuffleMachine()
    del CONFIG['HOME'], CONFIG['SHORTCUT']
    view, imgs = home_list(m)
    assert m.call(address=home_hook[0], args=(m.top, 0, 0, 0), gap=0) == 0
