def home_swap_motion():
    CONFIG.update(SHORTCUT='0', HOME='0')
    m = ShuffleMachine()
    del CONFIG['SHORTCUT'], CONFIG['HOME']
    m.rockbox_mode = 0
    view, imgs = home_list(m)
    assert m.call(address=home_hook[0], args=(m.top, 0, 0, 0), gap=0) == 0
    m.mock('widget_animator_prop_create', 'widget_animator_prop_set_params', 'widget_animator_start')
    sets = named(m, m.top, 'list_view_homeset')
    set_motion(m, 'swap', 300, 2)
    f, ctx = m.handler(named(m, m.top, 'img_settings'), O['EVT_CLICK'])

    def push():
        m.calls = []
        m.call(address=f, args=(ctx, m.event, 0, 0), gap=0)
        return [c for c in m.calls if c[0] == 'widget_animator_prop_create']
    assert push()[0][2] == 300 and m.nodes[sets]['animated_easing'] == 2
    m.advance(299)
    assert signed(m.get(sets + O['W_X'])) > 0
    m.advance(1)
    assert m.get(sets + O['W_X']) == 0
    m.call(O['KEY_RETURN'])
    push()
    m.advance(100)
    x = signed(m.get(sets + O['W_X']))
    assert 0 < x < 375
    m.call(O['KEY_RETURN'])
    assert push()
    assert signed(m.get(sets + O['W_X'])) == 375
    m.advance(300)
    assert m.get(sets + O['W_X']) == 0
    m.call(O['KEY_RETURN'])
    m.advance(300)
    set_motion(m, 'swap', 0, 0)
    assert not push() and m.nodes[sets]['visible'] and (m.get(sets + O['W_X']) == 0)
    passed()
