def oled_client(pm, fail=lambda page: False):
    oled_set(pm, fail)
    return pm.call(address=payload_syms['client_h'], args=(0, 0, 0, 0), gap=0)

def page_bar(pm):
    t = pm.node('hscroll_label', 'label_title')
    pm.word(t + O['W_W'], 98)
    b = bar_of(pm, t)
    pm.call(address=HOOKS['widget_on_paint_background'][0], args=(b, pm.canvas, 0, 0), gap=0)
    return t

def oled_page_bar(pm):
    t = pm.node('hscroll_label', 'label_title')
    pm.word(t + O['W_W'], 98)
    b = oled_bar(pm, t)
    pm.call(address=HOOKS['widget_on_paint_background'][0], args=(b, pm.canvas, 0, 0), gap=0)
    return t

def bar_reads(pm, bar):
    pm.call(address=payload_syms['title_gone'], args=(0, 0, 0, 0), gap=0)
    pm.call(address=payload_syms['bar_title_sync'], args=(pm.top, 0, 0, 0), gap=0)
    return pm.nodes[bar]['text']

def plist(pm, caption, n, item_h, keep=False):
    out = pm.alloc(4) if keep else 0
    return pm.call(address=payload_syms['page_list'], args=(pm.top, pm.top, out, pm.string(caption)), stack=(n, item_h), gap=0) & 4294967295

def prow(pm, view, i, caption, detail=None, into=False):
    f = payload_syms['page_row_detail_into' if into else 'page_row_detail']
    return pm.call(address=f, args=(view, i, pm.string(caption), pm.string(detail) if detail is not None else 0), stack=(0,), gap=0) & 4294967295

def box(pm, w):
    return [signed(pm.get(w + O[k])) for k in ('W_X', 'W_Y', 'W_W', 'W_H')]

def page_kids(pm, kind):
    return [c for c in pm.nodes[pm.top]['children'] if pm.nodes[c]['type'] == kind]

def under_bar(pm, name):
    w = pm.node('window', name)
    pm.word(w + O['W_Y'], OLG.bar)
    pm.word(w + O['W_PARENT'], pm.wm)
    return w
