class MotionMachine(UiLoad, CoverflowMachine):
    pass

def motion_machine():
    SETUP[:] = [lambda k: (k.config.update(LIGHT='1'), k)]
    try:
        m = MotionMachine()
    finally:
        SETUP.clear()
    m.handlers[syms['widget_set_prop_str']] = 'widget_set_prop_str'
    return m

def hint_writes(m):
    return sum((c[0] == 'widget_set_prop_str' and m.text(c[2]) in HINT_PROPS for c in m.calls))

def motion_load(m, name, kind='window', **props):
    w = m.node(kind, name.rsplit('/')[-1])
    m.nodes[w].update(props)
    ui_loaded(m, name, w)
    return w

def motion_open(m, name):
    return m.call(address=payload_syms['page_open'], args=(m.string(name), 0, 0, 0), gap=0) & 4294967295

def motion_over(m, name):
    m.nodes[m.wm] = {'children': [m.node('window', name), m.node('window', 'opening')]}
