def library_page():
    lm = oled_set(ShuffleMachine())
    lstock = []
    for i in range(11):
        kids = [lm.node('image'), lm.node('hscroll_label', text=f'Row {i}'), lm.node('image')]
        h = 28
        for c, (x, w) in zip(kids, ((8, 52), (72, 253), (282, 50))):
            for k, v in zip(('W_X', 'W_W', 'W_H'), (x, w, h)):
                lm.word(c + O[k], v)
        lb = lm.node('button', children=kids)
        lm.word(lb + O['W_X'], 20)
        lstock.append(lm.node('list_item', children=[lb]))
    lv = lm.node('scroll_view', 'scroll_view_localmusic', lstock)
