class RateMachine(FileMocks, ShuffleMachine):

    def __init__(self, saved=b''):
        super().__init__()
        self.budget = 2000000
        self.word(O['MCL_POS'], 1)
        self.file_mocks('r:', {'/mnt/data/ringnav-ratings': saved} if saved else {})
        self.fav_songs = []
        for n in ('getAllFav', 'fseek@GLIBC_2.0', 'ftell@GLIBC_2.0', 'taglib_file_new', 'taglib_file_audioproperties', 'taglib_file_free'):
            self.handlers[syms[n]] = 'r:' + n
        self.lengths = {}
        self.probed = []
        duration_syscalls(self)
        self.handlers[16777264] = 'r:length'
        self.handlers[FAV_CLICK] = 'r:fav_click'
        self.fav = self.node('image', 'img_fav')
        self.word(self.fav + O['W_X'], 303)
        self.word(self.fav + O['W_Y'], 176)
        self.word(self.fav + O['W_W'], 50)
        self.word(self.fav + O['W_H'], 50)
        self.nodes[self.fav]['image'] = 'play_unfav'
        self.np = self.node('window', 'playing_page', [self.node('view', 'view_album', [self.fav])])
        self.word(self.np + O['W_W'], 375)
        self.word(self.np + O['W_H'], 320)
        self.word(self.np + O['W_PARENT'], self.wm)
        for w in self.nodes[self.np]['children']:
            self.word(self.fav + O['W_PARENT'], w)
            self.word(w + O['W_PARENT'], self.np)
        em = self.alloc(4)
        it = self.alloc(40)
        self.word(self.fav + O['W_EMITTER'], em)
        self.word(em, it)
        self.word(it + O['EMIT_TYPE'], O['EVT_CLICK'])
        self.word(it + 12, FAV_CLICK)
        self.word(it, self.np)
        playing = HOOKS['playing_page_init'][0]
        self.handlers[playing + 12] = 'stock_playing'
        self.top = self.np
        self.stack = [self.np]
        assert self.call(address=playing, args=(self.np, 0, 0, 0), gap=0) == 0

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('r:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        ret = 0
        self.calls.append((name, a, b, c))
        if name in ('fopen', 'fread', 'fwrite', 'fclose', 'rename'):
            ret = self.file_op(u, name, a, b, c, d)
        elif name == 'fseek':
            ret = 0
        elif name == 'ftell':
            ret = len(self.files[self.open_files[a][0]])
        elif name == 'taglib_file_new':
            assert b == 1
            path = self.text(a)
            self.probed.append(path)
            if path in self.lengths:
                ret = self.alloc(8)
                props = self.alloc(8)
                vt = self.alloc(16)
                self.word(props, vt)
                self.word(vt + 12, 16777264)
                self.word(ret, props)
                self.word(props + 4, self.lengths[path])
        elif name == 'taglib_file_audioproperties':
            ret = self.get(a)
        elif name == 'length':
            ret = self.get(a + 4)
        elif name == 'pick':
            self.word(O['MCL_POS'], self.seq.pop(0))
            ret = 1
        elif name == 'getAllFav':
            self.deqs[self.get(syms['tools_pdeq_directory'])][1] = [self.copy('stSongInfo', e) for e in self.fav_songs]
            ret = len(self.fav_songs)
        elif name == 'fav_click':
            assert a == self.np
            t = self.names()[self.get(O['MCL_POS'])]
            self.favs ^= {t}
            self.nodes[self.fav]['image'] = 'play_fav' if t in self.favs else 'play_unfav'
        self.returns(ret, clobber=True)

    def kept(self):
        data = self.files.get('/mnt/data/ringnav-ratings', b'')
        return sorted((v for v in struct.unpack(f'<{len(data) // 4}I', data) if v))

    def badge(self):
        w = self.nodes[self.get(self.fav + O['W_PARENT'])]['children'][-1]
        return self.nodes[w].get('text') if self.nodes[w]['visible'] else None

    def panel(self):
        p = [w for w in self.nodes[self.np]['children'] if self.nodes[w]['type'] == 'hscroll_label']
        return p[0] if p and self.nodes[p[0]]['visible'] else None

    def hearts(self):
        p = self.panel()
        return [self.nodes[h]['image'] for h in self.nodes[p]['children'] if self.nodes[h]['type'] == 'image']

    def caption(self):
        return self.nodes[self.nodes[self.panel()]['children'][0]]['text']

    def tap(self, press=True):
        if press:
            f, ctx = self.handler(self.fav, O['EVT_POINTER_DOWN'])
            self.call(address=f, args=(ctx, self.event, 0, 0), gap=0)
        f, ctx = self.handler(self.fav, O['EVT_CLICK'])
        return self.call(address=f, args=(ctx, self.event, 0, 0), gap=0)

    def heart(self, ms=O['RATE_HOLD_MS']):
        self.touch()
        f, ctx = self.handler(self.fav, O['EVT_POINTER_DOWN'])
        self.call(address=f, args=(ctx, self.event, 0, 0), gap=0)
        self.pressed = 1
        self.advance(ms, clear=False)
        self.pressed = 0

