class RootMachine(ShuffleMachine):

    def __init__(self, root=None, otg=0, card=(('Music', 4), ('Podcasts', 4), ('notes.txt', 8))):
        super().__init__()
        self.card = list(card)
        self.byte(syms['g_otg_status'], otg)
        if root is not None:
            self.config['FOLDERROOT'] = root
        self.stacks = {}
        for g in ('g_yoffset_save', 'g_index_save'):
            h = self.alloc(4)
            self.word(syms[g], h)
            self.stacks[h] = []
        for n in ('stack_empty', 'stack_top', 'stack_pop', 'strcpy@GLIBC_2.0'):
            self.handlers[syms[n]] = 'r:' + n
        self.handlers.pop(syms['folder_reset_variable'])
        self.mock('strstr@GLIBC_2.0')
        for n in ('folder', 'folder_top'):
            self.handlers[int(manifest['patch_symbols'][f'stock_{n}_trampoline'], 16)] = 'stock_' + n
        self.win = self.node('window', 'folder_page')
        self.byte(syms['g_folder_layer'], 1)

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('r:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        a, b = (u.reg_read(REGS[0]), u.reg_read(REGS[1]))
        ret = 0
        self.calls.append((name, a, b))
        if name == 'stack_empty':
            ret = int(not self.stacks[a])
        elif name == 'stack_top':
            ret = self.stacks[a][-1]
        elif name == 'stack_pop':
            self.stacks[a].pop()
        elif name == 'strcpy':
            self.u.mem_write(a, self.text(b).encode() + b'\x00')
            ret = a
        self.returns(ret, clobber=True)

    def push(self, yoffset, index):
        for g, v in (('g_yoffset_save', yoffset), ('g_index_save', index)):
            e = self.alloc(4)
            self.word(e, v)
            self.stacks[self.get(syms[g])].append(e)

    def open(self):
        self.calls = []
        assert self.call(address=HOOKS['folder_page_init'][0], args=(self.win, 0, 0, 0), gap=0) == 0
        return (self.text(syms['g_folder_path']), self.u.mem_read(syms['g_folder_layer'], 1)[0])

    def back(self):
        out = self.alloc(8)
        self.word(out, 7)
        self.word(out + 4, 9)
        ret = self.call(address=HOOKS['folder_back'][0], args=(out, out + 4, 0, 0), gap=0)
        return (ret, self.text(syms['g_folder_path']), self.u.mem_read(syms['g_folder_layer'], 1)[0], (self.get(out), self.get(out + 4)))
