class GoMachine(RootMachine):

    def __init__(self, path, dirs=(), otg=0):
        super().__init__(otg=otg)
        self.handlers[syms['navigator_to']] = 'q:navigator_to'
        self.dirs = set(dirs)
        self.word(self.row(0) + O['REC_PATH'], self.string(path))

    def hook(self, u, address, size, unused):
        folder = address == syms['navigator_to'] and self.text(u.reg_read(REGS[0])) == 'folder_page'
        super().hook(u, address, size, unused)
        if folder:
            self.win = self.top
            self.nested(HOOKS['folder_page_init'][0], self.win, 0)

    def menu(self):
        self.press(5)
        assert self.hold() == 11
        got = (self.nodes[self.title]['text'], self.labels())
        self.release()
        return got

    def go(self):
        self.calls = []
        self.pick(len(SONG_MENU))
        self.advance(0)
