class ThumbMachine(DepthMachine):

    def __init__(self, data):
        super().__init__()
        self.data = data
        self.thumbs = []
        self.forks = 0
        self.ff_pid = -1
        self.open_files = {}
        for n in ('fopen@GLIBC_2.2', 'fread@GLIBC_2.0', 'fseek@GLIBC_2.0', 'fclose@GLIBC_2.2', 'access@GLIBC_2.0', 'memcmp@GLIBC_2.0', 'toolsThumbSpecCover', 'fork@GLIBC_2.0', 'waitpid@GLIBC_2.0', 'pthread_mutex_lock@GLIBC_2.0', 'pthread_mutex_unlock@GLIBC_2.0'):
            self.handlers[syms[n]] = 'p:' + n

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        a, b, c, d = [u.reg_read(r) for r in REGS]
        if not name.startswith('p:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        ret = 0
        if name == 'fopen':
            if self.text(a) in self.data:
                ret = self.alloc(4)
                self.open_files[ret] = [self.data[self.text(a)], 0]
        elif name == 'fread':
            f = self.open_files.get(d, [b'', 0])
            chunk = f[0][f[1]:f[1] + b * c]
            f[1] += len(chunk)
            self.u.mem_write(a, chunk)
            ret = len(chunk) // b
        elif name == 'fseek':
            assert c == 0
            self.open_files[a][1] = b
        elif name == 'access':
            ret = 0 if self.text(a) in self.data else -1
        elif name == 'memcmp':
            ret = 0 if bytes(self.u.mem_read(a, c)) == bytes(self.u.mem_read(b, c)) else 1
        elif name == 'toolsThumbSpecCover':
            self.thumbs.append((self.text(a), self.text(b), c, d))
            ret = 1
        elif name == 'fork':
            self.forks += 1
            ret = self.ff_pid
        elif name == 'waitpid':
            self.u.mem_write(b, struct.pack('<i', 1 << 8))
            ret = a
        self.calls.append((name, a, b, c))
        self.returns(ret, clobber=True)

def png_head(w, h):
    return b'\x89PNG\r\n\x1a\n' + struct.pack('>I4sII', 13, b'IHDR', w, h) + bytes(9)

def frame_jpeg(sof, w, h):
    return b'\xff\xd8' + JFIF + b'\xff' + bytes([sof]) + struct.pack('>HBHHB', 17, 8, h, w, 3) + bytes(9) + b'\xff\xda' + bytes(12)
