class SpotMachine(CardMachine):
    """CardMachine's card and files, plus librespot's side: system() starts, the monotonic clock is
    self.now, the player's status, and the thumbnailer (a .jpg it makes is a file)."""

    def __init__(self, files):
        super().__init__({}, files)
        for n in ('system@GLIBC_2.0', 'clock_gettime@GLIBC_2.2', 'toolsThumbSpecCover', 'pthread_mutex_lock@GLIBC_2.0', 'pthread_mutex_unlock@GLIBC_2.0', 'sleep_ms', 'mclGetPlayStatus', 'connect@GLIBC_2.0'):
            self.handlers[syms[n]] = 's:' + n
        self.alive = True
        for x in ('stream', 'start_player'):
            tramp = int(manifest['patch_symbols'][f'stock_{x}_trampoline'], 16)
            self.handlers[tramp] = 'stock_' + x
            self.u.hook_add(UC_HOOK_CODE, self.hook, begin=tramp, end=tramp)
        self.play = 1
        self.systems = []
        self.thumbs = []
        self.on_sleep = None
        self.handlers.pop(syms['mclStartPlayer'])
        self.handlers[HOOKS['main_loop_sleep_default'][0] + 12] = 'stock_sleep'
        self.handlers[HOOKS['window_manager_dispatch_input_event'][0] + 12] = 'stock_input'

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('s:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        ret = 0
        if name == 'system':
            self.systems.append(self.text(a))
        elif name == 'clock_gettime':
            assert a in (1, 7)
            self.word(b, self.now // 1000)
            self.word(b + 4, self.now % 1000 * 1000000)
        elif name == 'toolsThumbSpecCover':
            self.thumbs.append((self.text(a), self.text(b), c, d))
            ret = 1 if self.text(a) in self.files else 0
            if ret:
                self.files[self.text(b)] = bytearray(b'jpeg')
        elif name == 'sleep_ms':
            self.now += a
            if self.on_sleep:
                self.on_sleep()
        elif name == 'mclGetPlayStatus':
            ret = self.play
        elif name == 'connect':
            assert self.text(b + 2) == SOCK
            ret = 0 if self.alive else -1
        self.calls.append((name, a, b, c))
        self.returns(ret, clobber=True)

    def state(self, state, position=0, at=None, cover=0, track='t1', title='Song', artist='A, B', album='LP', duration=200000):
        self.files[STATE] = bytearray(f'state={state}\ntrack={track}\ntitle={title}\nartist={artist}\nalbum={album}\nduration={duration}\nposition={position}\nat={(self.now if at is None else at)}\ncover={cover}\n'.encode())

    def poll(self, ms=500):
        self.now += ms
        self.call(address=HOOKS['window_manager_dispatch_input_event'][0], args=(self.wm, self.event, 0, 0), gap=0)
        self.calls = []
        self.sent = []
        self.call(address=HOOKS['main_loop_sleep_default'][0], args=(4660, 0, 0, 0), gap=0, clear=False)
        return [c[0] for c in self.calls]

    def key(self, k):
        self.sent = []
        self.calls = []
        return self.call(k, gap=0, clear=False)
