from build import TIMEZONES, TIMEZONE_ORDER, timezone_offset

class TimezoneMachine(Machine):

    def __init__(self):
        super().__init__()
        self.mock('strcpy@GLIBC_2.0')

    def hook(self, u, address, size, unused):
        if self.handlers.get(address) != 'strcpy@GLIBC_2.0':
            return super().hook(u, address, size, unused)
        a, b = [u.reg_read(r) for r in REGS[:2]]
        self.u.mem_write(a, self.text(b).encode() + b'\x00')
        self.returns(a, clobber=True)
