class ZoneRowMachine(TimezoneMachine):
    tz = TIMEZONES[0][1]

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address)
        if name == 'toolsSetTimeZone':
            self.tz = self.text(u.reg_read(REGS[0]))
        if name != 'localtime_r':
            return super().hook(u, address, size, unused)
        self.calls.append((name,))
        label = next((l for l, z in TIMEZONES if z == self.tz))
        tm = u.reg_read(REGS[1])
        self.word(tm + 36, timezone_offset(label) * 60 + 3600 * (self.tz in SUMMER) & 4294967295)
        self.returns(tm, clobber=True)
