def stream_rows(m):
    """Streaming's page over stock's one Tidal row: the hook's rows' buttons by their labels, in order."""
    tidal = m.node('list_item', '', [m.node('image', image='list_tidal')])
    view = m.node('scroll_view', 'scroll_view_streamsset', [tidal])
    m.top = m.node('window', 'stream_page', [view])
    assert m.call(address=HOOKS['stream_page_init'][0], args=(m.top, 5, 0, 0), gap=0, count=5000000) == 0
    rows = {}
    for r in m.nodes[view]['children'][1:]:
        b = m.nodes[r]['children'][0]
        rows[m.nodes[m.nodes[b]['children'][1]]['text']] = b
    return rows

def stream_page(m):
    """Stock Streaming's one Tidal row, then the hook's Spotify, Tidal Downloads, Internet Radio and AirPlay
    rows; returns Spotify's button."""
    view = m.node('scroll_view', 'scroll_view_streamsset', [m.node('list_item')])
    m.top = m.node('window', 'stream_page', [view])
    assert m.call(address=HOOKS['stream_page_init'][0], args=(m.top, 5, 0, 0), gap=0, count=5000000) == 0 and m.calls[0][0] == 'stock_stream'
    assert len(m.nodes[view]['children']) == 6
    tidal = m.nodes[m.nodes[view]['children'][2]]['children'][0]
    icon, label = m.nodes[tidal]['children'][:2]
    assert m.nodes[icon]['image'] == 'list_tidal' and m.nodes[label]['text'] == 'Tidal Downloads'
    top = m.top
    f, ctx = m.handler(tidal, O['EVT_CLICK'])
    m.calls = []
    assert m.call(address=f, args=(ctx, m.event, 0, 0), gap=0, count=5000000) == 0
    assert [m.text(c[1]) for c in m.calls if c[0] == 'toolsLoadDirectory'] == ['/mnt/mmc/.tidal']
    assert m.nodes[m.top]['name'] == 'tidal_downloads' and empty_titles(m) == ['No Downloads Yet']
    f, ctx = m.handler(m.top, O['EVT_DESTROY'])
    m.call(address=f, args=(ctx, m.event, 0, 0), gap=0)
    m.top = top
    airplay = m.nodes[m.nodes[view]['children'][4]]['children'][0]
    icon, label = m.nodes[airplay]['children'][:2]
    assert m.nodes[icon]['image'] == 'stream_airplay' and m.nodes[label]['text'] == 'AirPlay'
    top = m.top
    f, ctx = m.handler(airplay, O['EVT_CLICK'])
    m.calls = []
    assert m.call(address=f, args=(ctx, m.event, 0, 0), gap=0) == 0
    assert [m.text(c[1]) for c in m.calls if c[0] == 'navigator_to'] == ['systemset/netservice_page']
    m.top = top
    return m.nodes[m.nodes[view]['children'][1]]['children'][0]

def spot_open(m, button):
    """The row, then (librespot on the card: the browser) its Now Playing page."""
    f, ctx = m.handler(button, O['EVT_CLICK'])
    assert m.call(address=f, args=(ctx, m.event, 0, 0), gap=0, count=5000000) == 0
    if BIN in m.files:
        if m.nodes[m.top]['name'] == 'spotbrowse_page':
            m.browser = m.top
        assert m.call(address=payload_syms['spot_np'], args=(0, 0, 0, 0), gap=0, count=5000000) == 0
    m.page = m.top
    assert m.nodes[m.page]['name'] == 'spotify_page'
    return m.page

