class RadioMachine(SpotMachine):
    """SpotMachine's side, plus Wi-Fi and demo's libcurl: perform hands reply to the write callback."""

    def __init__(self, files=None):
        super().__init__(files or {})
        for n in ('curl_easy_init', 'curl_easy_setopt', 'curl_easy_perform', 'curl_easy_getinfo', 'curl_easy_cleanup', 'get_wifisignal', 'mkdir@GLIBC_2.0'):
            self.handlers[syms[n]] = 'r:' + n
        self.mock('fflush@GLIBC_2.0', 'fsync@GLIBC_2.0', 'fileno@GLIBC_2.0', 'ferror@GLIBC_2.0')
        self.wifi = 3
        self.reply = b''
        self.code = 200
        self.codes = []
        self.location = ''
        self.opts = {}

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('r:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        ret = 0
        if name == 'get_wifisignal':
            ret = self.wifi
        elif name == 'mkdir':
            self.tree[self.text(a)] = []
        elif name == 'curl_easy_init':
            ret = 20816
            self.opts = {}
        elif name == 'curl_easy_setopt':
            self.opts[b] = self.text(c) if b in (10002, 10018, 10065) else c
        elif name == 'curl_easy_perform' and 20011 not in self.opts:
            ret = 0
        elif name == 'curl_easy_perform':
            data = self.alloc(len(self.reply) + 7 & ~3)
            u.mem_write(data, self.reply)
            took = self.nested(self.opts[20011], data, 1, len(self.reply), self.opts.get(10001, 0))
            ret = 0 if took == len(self.reply) and self.code else 23
        elif name == 'curl_easy_getinfo' and b == 1048607:
            text = self.alloc(len(self.location) + 4)
            u.mem_write(text, self.location.encode() + b'\x00')
            self.word(c, text)
        elif name == 'curl_easy_getinfo':
            self.word(c, self.codes.pop(0) if self.codes else self.code)
        self.calls.append((name, a, b, c))
        self.returns(ret, clobber=True)

    def stream(self):
        view = self.node('scroll_view', 'scroll_view_streamsset', [self.node('list_item')])
        self.top = self.node('window', 'stream_page', [view])
        assert self.call(address=HOOKS['stream_page_init'][0], args=(self.top, 5, 0, 0), gap=0, count=5000000) == 0
        return self.nodes[self.nodes[view]['children'][3]]['children'][0]

    def click(self, w):
        f, ctx = self.handler(w, O['EVT_CLICK'])
        assert self.call(address=f, args=(ctx, self.event, 0, 0), gap=0, count=5000000) == 0
        self.advance(0, clear=False)

    def rows(self):
        return self.nodes[self.find('scroll_view', self.page)]['children']

    def row(self, i):
        self.click(self.rows()[i])

    def labels(self, w=None):
        """Texts still linked below w (page_list's destroy_children mock only unlinks)."""

        def linked(x, w):
            while x != w:
                parent = self.get(x + O['W_PARENT'])
                if parent not in self.nodes or x not in self.nodes[parent]['children']:
                    return False
                x = parent
            return True
        w = w or self.page
        return [n.get('text', '') for x, n in self.nodes.items() if n['type'] == 'hscroll_label' and linked(x, w)]

    def back(self, w=None):
        """Return on page w (the radio list by default), and its timers."""
        w = w or self.page
        f, ctx = self.handler(w, O['EVT_KEY_UP'])
        ev = self.alloc(64)
        self.word(ev, O['EVT_KEY_UP'])
        self.word(ev + O['EVENT_KEY'], O['KEY_RETURN'])
        assert self.call(address=f, args=(ctx, ev, 0, 0), gap=0, count=5000000) == 11
        self.advance(0, clear=False)

    def destroy(self, w):
        f, ctx = self.handler(w, O['EVT_DESTROY'])
        self.call(address=f, args=(ctx, self.event, 0, 0), gap=0)

    def worker(self):
        worker, arg = self.threads[-1]
        assert self.call(address=worker, args=(arg, 0, 0, 0), gap=0, count=5000000) == 0
        self.advance(250)

def radio_open(m):
    button = m.stream()
    icon, label = m.nodes[button]['children'][:2]
    assert m.nodes[icon]['image'] == 'stream_radio' and m.nodes[label]['text'] == 'Internet Radio' and (not m.nodes[button].get('name'))
    m.click(button)
    m.page = m.top
    assert m.nodes[m.page]['name'] == 'radio_page'
    return m.page
