class LyricSearchMachine(RadioMachine):

    def __init__(self):
        super().__init__()
        self.written = {}
        self.json = {}
        for n in ('fopen@GLIBC_2.2', 'fputs@GLIBC_2.0', 'fclose@GLIBC_2.2', 'cJSON_Parse', 'cJSON_GetArraySize', 'cJSON_GetArrayItem', 'cJSON_GetObjectItem', 'cJSON_Delete'):
            self.handlers[syms[n]] = 'ls:' + n
        self.handlers[HOOKS['kugou_obtainlyric'][0] + 12] = 'ls:kugou'
        self.handlers.pop(syms['online_getkeyword_info'], None)
        self.mock('pthread_mutex_lock@GLIBC_2.0', 'pthread_mutex_unlock@GLIBC_2.0')

    def item(self, v):
        a = self.alloc(48)
        self.json[a] = v
        self.word(a + 16, self.string(v) if isinstance(v, str) else 0)
        return a

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if name == 'r:curl_easy_perform':
            self.reply = self.replies.pop(0) if self.replies else b'[]'
            self.urls.append(self.opts[10002])
        if not name.startswith('ls:'):
            return super().hook(u, address, size, unused)
        name = name[3:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        ret = 0
        if name == 'fopen':
            self.fpath = self.text(a)
            self.written[self.fpath] = b''
            ret = 33554688
        elif name == 'fputs':
            self.written[self.fpath] += self.raw(a)
        elif name == 'cJSON_Parse':
            ret = self.item(json.loads(self.text(a)))
        elif name == 'cJSON_GetArraySize':
            ret = len(self.json[a])
        elif name == 'cJSON_GetArrayItem':
            ret = self.item(self.json[a][b])
        elif name == 'cJSON_GetObjectItem':
            v = self.json[a]
            key = self.text(b)
            ret = self.item(v[key]) if isinstance(v, dict) and key in v else 0
        self.calls.append((name, a, b, c))
        self.returns(ret, clobber=True)

    def search(self, title, artist, *replies, code=200):
        """replies: one a request, in turn (then [])."""
        key = 10831348
        self.u.mem_write(key, bytes(1536))
        self.u.mem_write(key + 512, title.encode())
        self.u.mem_write(key + 1280, artist.encode())
        self.replies, self.code, self.written, self.calls, self.urls = (list(replies), code, {}, [], [])
        self.u.mem_write(BIG, bytes(self.big - BIG))
        self.big = BIG
        return self.call(address=HOOKS['kugou_obtainlyric'][0], args=(self.string(f'{title}/{artist}'), self.string('/tmp/oslyric_7'), 0, 0), gap=0, count=5000000)
