from build import LYRIC_SAVE_CALL

class LyricSaveMachine(AlbumLyricsMachine):

    def __init__(self, files):
        super().__init__()
        self.files = dict(files)
        self.open_files = {}
        self.unlinked = []
        self.fail_write = False
        for n in ('fopen@GLIBC_2.2', 'fread@GLIBC_2.0', 'fwrite@GLIBC_2.0', 'fclose@GLIBC_2.2', 'rename@GLIBC_2.0', 'unlink@GLIBC_2.0'):
            self.handlers[syms[n]] = 'lv:' + n

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('lv:'):
            return super().hook(u, address, size, unused)
        name = name[3:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        ret = 0
        if name == 'fopen':
            path, mode = (self.text(a), self.text(b))
            if mode == 'rb' and path in self.files or (mode == 'wb' and (not self.fail_write)):
                ret = 33554432 + 16 * len(self.open_files)
                self.open_files[ret] = [path, mode, 0, b'']
        elif name == 'fread':
            f = self.open_files[d]
            data = self.files[f[0]][f[2]:f[2] + b * c]
            f[2] += len(data)
            u.mem_write(a, data)
            ret = len(data) // b
        elif name == 'fwrite':
            self.open_files[d][3] += bytes(u.mem_read(a, b * c))
            ret = c
        elif name == 'fclose':
            path, mode, _, data = self.open_files.pop(a)
            if mode == 'wb':
                self.files[path] = data
        elif name == 'rename':
            self.files[self.text(b)] = self.files.pop(self.text(a))
        elif name == 'unlink':
            self.unlinked.append(self.text(a))
            self.files.pop(self.text(a), None)
        self.returns(ret, clobber=True)

    def save(self, name):
        cmd = self.alloc(1024)
        fmt = 7890928
        self.call(address=payload_syms['ringnav_lyric_save'], args=(cmd, 1024, fmt, self.string('/tmp/oslyric_7')), stack=(self.string(name),), gap=0)
        return self.text(cmd)
