class BrowseMachine(RadioMachine):
    """RadioMachine's helpers, librespot on the card and a fake backend on its browse socket: serve(op,
    args) answers (status, message, cursor, rows), or raw bytes; no serve, no socket. A subclass names
    another app: its socket, its Streaming row and the page it opens."""
    browse, bin, page_name = (BROWSE, BIN, 'spotbrowse_page')

    def __init__(self, files=None):
        super().__init__({self.bin: bytearray(), **(files or {})})
        for n in ('socket@GLIBC_2.0', 'connect@GLIBC_2.0', 'send@GLIBC_2.0', 'select@GLIBC_2.0', 'recv@GLIBC_2.0', 'fcntl@GLIBC_2.28'):
            self.handlers[syms[n]] = 'x:' + n
        shut = payload_syms['spot_shut']
        self.handlers[shut] = 'x:spot_shut'
        self.u.hook_add(UC_HOOK_CODE, self.hook, begin=shut, end=shut)
        self.serve = None
        self.requests = []
        self.wire = []
        self.out = b''
        self.pending = b''
        self.stalled = False

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if name == 'widget_set_prop_int' and self.text(u.reg_read(REGS[1])) == 'virtual_h':
            self.word(u.reg_read(REGS[0]) + O['VIEW_CONTENT_H'], u.reg_read(REGS[2]))
        if not name.startswith('x:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        ret = 0
        if name == 'socket':
            assert a == 1 and b in (1, 2)
            ret = 9 if b == 2 else 7
            if b == 2:
                self.out = b''
                self.pending = b''
        elif name == 'connect' and a != 9:
            assert self.text(b + 2) == SOCK
            ret = 0 if self.alive else -1
        elif name == 'connect':
            assert self.text(b + 2) == self.browse
            ret = 0 if self.serve else -1
        elif name == 'fcntl':
            assert (a, b, c) == (9, 4, 128)
        elif name == 'send':
            if a == 9:
                self.out += bytes(u.mem_read(b, c))
            else:
                self.sent.append((a, bytes(u.mem_read(b, c)), c, d))
            ret = c
        elif name == 'spot_shut':
            self.wire.append(self.out)
            head, line, end = self.out.decode().split('\n')
            assert head == 'Q2SPOT/1' and end == ''
            rid, op, *args = line.split('\t')
            self.requests.append((op, *args))
            got = self.serve(op, args)
            if isinstance(got, bytes):
                self.pending = got.replace(b'{id}', rid.encode())
            else:
                status, msg, cursor, rows = got
                self.pending = f'Q2SPOT/1\n{rid}\t{status}\t{msg}\t{cursor}\n'.encode() + b''.join((('\t'.join(r) + '\n').encode() for r in rows))
        elif name == 'select':
            assert a == 10 and bool(b) != bool(c)
            if self.stalled:
                self.now += 100
                ret = 0
            else:
                ret = 1
        elif name == 'recv':
            chunk = self.pending[:min(c, 1000)]
            self.pending = self.pending[len(chunk):]
            u.mem_write(b, chunk)
            ret = len(chunk)
        self.calls.append((name, a, b, c))
        self.returns(ret, clobber=True)

    def add_on_row(self):
        """Its Streaming row, as RadioMachine.stream: Spotify's."""
        return stream_rows(self)['Spotify']

    def open(self):
        if not getattr(self, 'button', 0):
            self.button = self.add_on_row()
        self.click(self.button)
        self.page = self.top
        assert self.nodes[self.page]['name'] == self.page_name

    def asked(self):
        """The request the worker is about to send (spotify.c's wk: buf at 32, len at 28), split."""
        wk = payload_syms['wk']
        head, line, _ = bytes(self.u.mem_read(self.get(wk + 32), self.get(wk + 28))).decode().split('\n')
        assert head == 'Q2SPOT/1'
        return tuple(line.split('\t')[1:])

    def answer(self, *reply):
        """The request in flight answered with reply, and the page's tick."""
        self.serve = (lambda op, args: reply[0]) if len(reply) == 1 else lambda op, args: reply
        self.worker()
        if self.page_name == 'spotbrowse_page' and self.get(payload_syms['wk'] + 32) and (self.asked() == ('caps',)):
            self.serve = lambda op, args: ('ok', '', '', [('op', name, '', '', '', '') for name in getattr(self, 'caps', ('download', 'downloadstatus', 'downloaded', 'playdownload'))])
            self.worker()

    def pick(self, i):
        self.nodes[self.find('scroll_view')]['_ringnav_index'] = i
        self.row(i)
