class PodMachine(AppMachine):
    app, manifest = ('podcasts', 'name=Podcasts\nsearch=Search Podcasts\nqr=0\n')

    def poll(self, ms=500):
        self.wms = getattr(self, 'wms', 0) + ms
        self.wall = (86400 + getattr(self, 'jump', 0) + self.wms // 1000, self.wall[1])
        return super().poll(ms)

    def hook(self, u, address, size, unused):
        if self.handlers.get(address) == 'unlink@GLIBC_2.0':
            self.unlinked.append(self.text(u.reg_read(UC_MIPS_REG_A0)))
        return super().hook(u, address, size, unused)
