def stream_songs(*names):
    m.tree[STREAM] = [(n, 8) for n in names]
    rs = []
    m.stats[STREAM] = m.stats.get(STREAM, 0) + 1
    for n in names:
        if n.endswith('.part'):
            continue
        r = m.song(n)
        m.word(r + O['REC_PATH'], m.string(f'{STREAM}/{n}'))
        m.stats[f'{STREAM}/{n}'] = 1
        rs.append(r)
    m.found = rs
    return rs
