def card_song(path, listing=True):
    d, n = path.rsplit('/', 1)
    r = m.song(n)
    m.word(r + O['REC_PATH'], m.string(path))
    m.files[path] = bytearray()
    m.stats[path] = 1
    if listing:
        m.listings.setdefault(d, []).append(r)
    return r

