def sign_list(body):
    return body + b'signature ' + signing.sign(signing.list_message(body), TEST_PEM).hex().encode() + b'\n'

def shelf_list(body=REPO_LIST, **tags):
    """body signed by the test key, the apps named (repo: tag) pinned to ZIP at tag."""
    lines = []
    for line in body.decode().splitlines(keepends=True):
        repo = line.split(' ')[0]
        if repo in tags:
            words = line.split(' ', 5)
            words[1:5] = [tags[repo], 'app.zip', str(len(ZIP)), hashlib.sha256(ZIP).hexdigest()]
            line = ' '.join(words)
        lines.append(line)
    return sign_list(''.join(lines).encode())

class ShelfMachine(RadioMachine):
    """RadioMachine with busybox's side scripted: unzip -l prints listing, unzip -o stages staged
    ((path, bytes), in find's order), find lists them; statfs has free bytes; renames kept in order;
    listed, once set, answers every sources.list fetch in reply's place. The test key is the release key."""

    def __init__(self, files=None):
        super().__init__(files)
        self.free = 1 << 32
        self.moves = []
        self.listing = ''
        self.staged = []
        self.listed = None
        self.mock('rmdir@GLIBC_2.0')
        test_key(self)

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if name == 'r:curl_easy_perform' and self.listed is not None and self.opts.get(10002, '').endswith('/sources.list'):
            reply, self.reply = (self.reply, self.listed)
            try:
                return super().hook(u, address, size, unused)
            finally:
                self.reply = reply
        if name == 'c:statfs@GLIBC_2.0':
            b = u.reg_read(UC_MIPS_REG_A1)
            self.word(b + 4, 4096)
            self.word(b + 28, self.free >> 12)
            self.returns(0, clobber=True)
            return
        if name == 'b:rename@GLIBC_2.0':
            self.moves.append(self.text(u.reg_read(UC_MIPS_REG_A1)))
        if name == 's:system@GLIBC_2.0':
            cmd = self.text(u.reg_read(UC_MIPS_REG_A0))
            out = cmd.split(' > ')[-1]
            if 'unzip -l' in cmd:
                self.files[out] = bytearray(self.listing.encode())
            elif 'unzip -o' in cmd:
                for path, data in self.staged:
                    self.files[cmd.split('-d ')[1].split(' ')[0] + '/' + path] = bytearray(data)
            elif ' find ' in cmd:
                self.files[out] = bytearray(''.join((path + '\n' for path, _ in self.staged)).encode())
            elif cmd.startswith('rm -rf /mnt/mmc/.q2/staging'):
                for f in [f for f in self.files if f.startswith('/mnt/mmc/.q2/staging')]:
                    del self.files[f]
        return super().hook(u, address, size, unused)

def apps_open(m):
    assert m.call(address=payload_syms['shelf_open'], args=(0, m.event, 0, 0), gap=0, count=5000000) == 0
    m.advance(0, clear=False)
    m.page = m.top
    assert m.nodes[m.page]['name'] == 'apps_page'

