class ResumeMachine(QueueMachine):

    def __init__(self, files=None):
        super().__init__()
        self.files = {} if files is None else files
        self.open = {}
        self.play = (0, 0)
        self.seeks = []
        self.opens = self.renames = 0
        self.handlers[sleep_hook + 12] = 'stock_sleep'
        for n in ('fopen@GLIBC_2.2', 'fread@GLIBC_2.0', 'fwrite@GLIBC_2.0', 'fclose@GLIBC_2.2', 'rename@GLIBC_2.0', 'access@GLIBC_2.0', 'time@GLIBC_2.0', 'player_playtime_and_length', 'fseek@GLIBC_2.0', 'ftell@GLIBC_2.0'):
            self.handlers[syms[n]] = 'r:' + n
        self.handlers[payload_syms['stock_seek_time_trampoline']] = 'r:player_seek_time'
        self.epoch = 1700000000
        self.mock('tk_snprintf', 'strstr@GLIBC_2.0')
        self.mock('pthread_mutex_lock@GLIBC_2.0', 'pthread_mutex_unlock@GLIBC_2.0')

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('r:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        ret = 0
        self.calls.append((name, a, b, c))
        if name == 'fopen':
            path, mode = (self.text(a), self.text(b))
            self.opens += path != RECORD and (path != '/proc/mounts' or not self.u.mem_read(syms['g_backlight_status'], 1)[0])
            if mode == 'rb' and path not in self.files:
                ret = 0
            else:
                ret = 33554432 + len(self.calls)
                self.open[ret] = [path, mode, 0, b'' if mode == 'wb' else self.files.get(path, b'')]
        elif name == 'fread':
            f = self.open[d]
            data = f[3][f[2]:f[2] + b * c]
            f[2] += len(data)
            self.u.mem_write(a, data)
            ret = len(data) // b
        elif name == 'fwrite':
            self.open[d][3] += bytes(self.u.mem_read(a, b * c))
            ret = c
        elif name == 'fseek':
            f = self.open[a]
            f[2] = signed(b) + (0, f[2], len(f[3]))[c]
        elif name == 'ftell':
            ret = self.open[a][2]
        elif name == 'fclose':
            path, mode, _, data = self.open.pop(a)
            if mode in ('wb', 'ab'):
                self.files[path] = data
        elif name == 'access':
            ret = 0 if self.text(a) in self.files else -1
        elif name == 'time':
            ret = self.epoch
        elif name == 'rename':
            self.renames += 1
            self.files[self.text(b)] = self.files.pop(self.text(a))
        elif name == 'player_playtime_and_length':
            if self.play[1]:
                self.word(a, self.play[0])
                self.word(b, self.play[1])
                ret = 1
            else:
                ret = -1
        elif name == 'player_seek_time':
            assert not isinstance(self, ResumeMachine) or not any((c[0] == 'stock_press_stamp' for c in self.calls))
            self.seeks.append(signed(a))
            self.play = (signed(a), self.play[1])
        self.returns(ret, clobber=True)

    def poll(self, sec, total=3600, pos=None, n=1):
        if pos is not None:
            self.word(O['MCL_POS'], pos)
        for _ in range(n):
            self.play = (sec, total)
            self.now += 1000
            assert self.call(address=sleep_hook, args=(4660, 0, 0, 0), gap=0) == 0
            sec = self.play[0]
        return self

    def places(self):
        data = self.files.get('/mnt/data/ringnav-resume', b'')
        return [(k, signed(v)) for k, v in struct.iter_unpack('<II', data) if k]

def playing(m, sec, total=3600, pos=None, n=1):
    m.poll(sec, total, pos)
    for _ in range(n - 1):
        m.poll(m.play[0] + 1, total)
    return m
