def home_after_hold(press):
    h = NavigationMachine()
    view, _ = home_list(h)
    h.order = [h.top]
    h.sync_order()
    h.paint(view)
    for _ in range(3):
        h.call()
    assert h.selected(view) == 3
    h.byte(LATCH, 1)
    h.handlers[inp + 12] = 'stock_input'
    if press:
        h.call(RET, address=inp, args=(h.wm, h.event, 0, 0), event_type=DOWN, gap=1000, clear=False)
    h.call(RET)
    return h.selected(view)
