def held_key(patched, changed=True):
    c = Machine(patched)
    c.mock('widget_on_keydown', 'widget_on_keyup')
    c.mock('log_get_log_level', prefix='one:')
    c.handlers[syms['widget_get_window_manager']] = 'window_manager'
    c.handlers.pop(syms['key_event_init'], None)
    ids = c.alloc(512)
    record = ids + O['INPUT_KEYS']
    sent = lambda: [x[0] for x in c.calls if x[0] in ('widget_on_keydown', 'widget_on_keyup')]

    def key(kind, gap):
        c.call(O['KEY_PLAY'], address=syms['input_device_status_on_input_event'], args=(ids, c.wm, c.event, 0), event_type=kind, gap=gap)
        return sent()

    def wait(ms):
        c.advance(ms)
        return sent()
    out = [key(O['EVT_KEY_DOWN'], 0), wait(1000)]
    pressed = c.get(record + O['INPUT_KEY_TIME'])
    if changed:
        c.call(address=syms['input_device_status_abort_all_pressed_keys'], args=(ids, 0, 0, 0), gap=0)
    return out + [key(O['EVT_KEY_DOWN'], 250), c.get(record + O['INPUT_KEY_TIME']) - pressed, wait(2000), key(O['EVT_KEY_UP'], 0), c.get(record)]
