def keyups(patched, handler):
    """{key: (lit, dark)} for each key handler doesn't pass untouched both ways: the functions it calls, then stop if it stops the key."""
    c = Machine(patched)
    c.handlers.clear()
    end = handler + 4
    names = {a: n for n, a in syms.items()}
    while c.get(end) >> 16 != 15388:
        end += 4
    c.byte(syms['g_wheelmode'], 1)

    def stub(u, address, size, _):
        if not handler <= address < end:
            c.calls.append(names.get(address))
            c.returns(0)
    c.u.hook_add(UC_HOOK_CODE, stub)
    out = {}
    for key in (O['KEY_RETURN'], O['KEY_PLAY'], O['KEY_PREV'], O['KEY_NEXT'], O['KEY_CENTER'], O['KEY_BACK_BTN'], O['KEY_FWD_BTN']):
        row = []
        for lit in (1, 0):
            c.byte(syms['g_backlight_status'], lit)
            ret = c.call(key, address=handler, args=(c.alloc(256), c.event, 0, 0), gap=0)
            assert ret in (0, 11), (hex(handler), key, ret)
            row.append(' '.join([n for n in c.calls if n not in (None, 'widget_lookup', 'widget_focused_widget_in_window')] + ['stop'] * (ret == 11)))
        if any(row):
            out[key] = tuple(row)
    return out

def stock_keyups():
    ret, play, prev, nxt, centre, rew, fwd = (O['KEY_' + k] for k in ('RETURN', 'PLAY', 'PREV', 'NEXT', 'CENTER', 'BACK_BTN', 'FWD_BTN'))
    stop = ('stop', '')
    wheel = {prev: stop, nxt: stop, centre: stop}
    every = {**wheel, ret: stop, play: stop, rew: stop, fwd: stop}
    for want, handlers in (({ret: ('on_return_onclick stop', '')}, (syms['on_common_keyup'], 4897844, 4874380, 4919120, 4926136, 5482800, 5474952, 4844400)), ({ret: stop}, (5452560, syms['on_specfolder_keyup'], 4852564)), ({**wheel, ret: ('dialog_quit', '')}, (4823964,)), ({**every, ret: ('dialog_quit', '')}, (4831176,)), ({**wheel, ret: stop}, (4860564,)), (every, (4822312,))):
        for handler in handlers:
            assert keyups(True, handler) == keyups(False, handler) == want, hex(handler)
    back = {ret: ('on_return_onclick stop', '')}
    assert keyups(True, 5495388) == back and keyups(False, 5495388) == {**back, centre: ('power_keyup_detect power_keyup_pending_custom stop', '')}
