class TagMachine(CardMachine):

    def __init__(self, files):
        super().__init__({}, files)
        self.stock_artist = b''
        self.handlers.pop(syms['toolsGetMusicInfo'], None)
        tramp = int(manifest['patch_symbols']['stock_music_info_trampoline'], 16)
        self.handlers[tramp] = 'stock_music_info'
        self.u.hook_add(UC_HOOK_CODE, self.hook, begin=tramp, end=tramp)

    def hook(self, u, address, size, unused):
        if self.handlers.get(address) != 'stock_music_info':
            return super().hook(u, address, size, unused)
        u.mem_write(u.reg_read(UC_MIPS_REG_A1) + 1408, self.stock_artist + b'\x00')
        self.returns(1)

    def album_artist(self, path, stock=b''):
        self.stock_artist = stock
        info = self.alloc(1696)
        p = self.alloc(256)
        self.u.mem_write(p, path.encode() + b'\x00')
        assert self.call(address=HOOKS['toolsGetMusicInfo'][0], args=(0, info, p, 0), gap=0) == 1
        return self.text(info + 1408)

def flac(*comments, picture=0):
    vc = struct.pack('<I', 6) + b'vendor' + struct.pack('<I', len(comments)) + b''.join((struct.pack('<I', len(c)) + c for c in comments))
    blocks = [(0, bytes(34))] + ([(6, bytes(picture))] if picture else []) + [(4, vc)]
    return bytearray(b'fLaC' + b''.join((bytes([t | (128 if i == len(blocks) - 1 else 0)]) + len(d).to_bytes(3, 'big') + d for i, (t, d) in enumerate(blocks))) + b'audio')
