class OggCoverMachine(TagMachine):

    def __init__(self, files):
        super().__init__(files)
        self.stock_covers = []
        self.ffmpeg = 0
        self.handlers.pop(syms['toolsGetAlbumCover'], None)
        tramp = int(manifest['patch_symbols']['stock_album_cover_trampoline'], 16)
        self.handlers[tramp] = 'stock_album_cover'
        self.u.hook_add(UC_HOOK_CODE, self.hook, begin=tramp, end=tramp)

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address)
        if name == 'stock_album_cover':
            self.stock_covers.append(self.text(u.reg_read(REGS[0])))
            return self.returns(1, clobber=True)
        if name != 'b:waitpid@GLIBC_2.0':
            return super().hook(u, address, size, unused)
        self.ffmpeg += 1
        self.files[self.dst + '.ff'] = bytearray(b'jpeg')
        self.word(u.reg_read(REGS[1]), 0)
        self.returns(u.reg_read(REGS[0]), clobber=True)

    def cover(self, track):
        self.stock_covers = []
        self.ffmpeg = 0
        self.dst = '/mnt/mmc/.sldp/x0.jpg'
        return self.call(address=payload_syms['coverflow_grid_cover'], args=(self.string(track), self.string(self.dst), 110, 110), gap=0)
