class ScanNoteMachine(TagMachine):
    STATM = b'30000 22750 1200 1 0 25000 0\n'

    def __init__(self, files):
        super().__init__(files)
        self.fds = {}
        self.seen = []
        for n in ('open', 'read', 'write', 'close'):
            self.handlers[syms[n + '@GLIBC_2.0']] = 's:' + n
        self.mock('snprintf@GLIBC_2.0')

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        a, b, c = (u.reg_read(r) for r in REGS[:3])
        ret = 0
        if name == 'stock_music_info':
            self.seen.append(bytes(self.files.get('/tmp/q2-scan-file', b'')))
        if not name.startswith('s:'):
            return super().hook(u, address, size, unused)
        if name == 's:open':
            path = self.text(a)
            ret = 4294967295
            if path == '/proc/self/statm' and b & 3 == 0:
                self.files[path] = bytearray(self.STATM)
            if path in self.files or b & 256:
                if b & 512 or path not in self.files:
                    self.files[path] = bytearray()
                ret = 100 + len(self.fds)
                self.fds[ret] = [path, b]
        elif name == 's:read':
            data = bytes(self.files[self.fds[a][0]][:c])
            u.mem_write(b, data)
            ret = len(data)
        elif name == 's:write':
            assert self.fds[a][1] & 3 == 1
            self.files[self.fds[a][0]] += bytes(u.mem_read(b, c))
            ret = c
        elif name == 's:close':
            self.fds.pop(a, None)
        self.returns(ret, clobber=True)
