class MonoMachine(QueueMachine):

    def __init__(self):
        super().__init__()
        self.flag = self.alloc(4)
        self.word(syms['g_equalizer_flag'], 1)
        for n in ('open', 'write', 'rename', 'mmap', 'close'):
            self.handlers[syms[n + '@GLIBC_2.0']] = 'mono:' + n

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('mono:'):
            return super().hook(u, address, size, unused)
        self.calls.append((name,))
        self.returns(self.flag if name == 'mono:mmap' else 3 if name == 'mono:open' else 4 if name == 'mono:write' else 0)
