def tint_machine(config, w=8, h=4, row=None, mode=0, fmt=3, clock=None):
    m = QueueMachine()
    m.config.update(config)
    m.handlers[payload_syms['peq_boot']] = 'stock_peq_boot'
    if clock:
        m.clock = clock
    m.call(address=payload_syms['ringnav_bootmode'], args=(3, 0, 0, 0), gap=0)
    fb = m.alloc(4 * w * h + 64)
    end = syms['widget_invalidate_force']
    for off, v in ((176, w), (180, h), (292, 4 * (row or w)), (296, fmt), (204, mode), (272, fb), (124, end), (248, 2), (252, 1), (256, 3), (260, 2)):
        m.word(m.lcd + off, v)
    for i in range(w * h):
        m.word(fb + 4 * i, 4278190080 | i * 460035)
    m.word(fb + 4 * (1 * w + 3), 4145165398)
    return (m, fb, end)

def tint_frame(m):
    m.calls = []
    m.call(address=syms['lcd_end_frame'], args=(m.lcd, 0, 0, 0), gap=0)
    return [c[1] for c in m.calls if c[0] == 'widget_invalidate_force']

