def blank(m):
    m.bands = []
    m.letters = []
    m.rounded = []
    m.image_draws = []
    m.calls = []

def screen_box(m, w):
    x, y, ww, h = wbox(m, w)
    for p in iter(lambda p=[w]: p.__setitem__(0, m.get(p[0] + O['W_PARENT'])) or p[0], 0):
        if p == m.top or p == m.wm:
            break
        x, y = (x + signed(m.get(p + O['W_X'])), y + signed(m.get(p + O['W_Y'])))
    return (x, y, ww, h)

def paint_canvas():
    SETUP[:] = [lambda k: (k.config.update(LIGHT='1'), k)]
    try:
        return QueueMachine()
    finally:
        SETUP.clear()

def ring(R):
    lk = paint_canvas()
