class WifiMachine(Machine):

    def __init__(self, pct, patched=True):
        super().__init__(patched)
        self.pct = pct
        self.mock('strstr@GLIBC_2.0', 'strncpy@GLIBC_2.0')
        for n in ('open', 'read', 'close', 'socket', 'ioctl'):
            self.handlers[syms[n + '@GLIBC_2.0']] = 'w:' + n

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('w:'):
            return super().hook(u, address, size, unused)
        assert u.reg_read(UC_MIPS_REG_T9) == address
        name = name[2:]
        a, b, c = (u.reg_read(r) for r in REGS[:3])
        ret = 0
        self.calls.append((name, a, b, c))
        if name == 'open':
            ret = 3 if self.pct is not None and self.text(a) == RX_SIGNAL else -1
        elif name == 'read':
            data = f'rssi:{self.pct}\nsignal_strength:{self.pct}\nsignal_qual:100\n'.encode()[:c]
            u.mem_write(b, data)
            ret = len(data)
        elif name == 'socket':
            ret = 5
        elif name == 'ioctl':
            assert (a, b) == (5, 35599)
            u.mem_write(self.get(c + 16), bytes([0, 0, 70, self.pct - 100 & 255]))
        self.returns(ret, clobber=True)

    def signal(self):
        return self.call(address=HOOKS['networkGetWifiSignal'][0], args=(0, 0, 0, 0), gap=0)

    def used(self):
        return [c[0] for c in self.calls if c[0] in ('open', 'read', 'close', 'socket', 'ioctl')]
