class SmartMixin:

    def __init__(self, *a, smart='1', **k):
        super().__init__(*a, **k)
        if smart:
            self.config['SMARTWIFI'] = smart
        self.handlers.pop(syms['write_int_config'], None)
        self.handlers[HOOKS['write_int_config'][0] + 12] = 'w:write'
        self.mock('remove@GLIBC_2.0', 'stop_wifisynclink', 'networkStart', 'networkStop')
        for n in ('networkGetConnectStatus', 'get_wifisignal'):
            self.handlers[syms[n]] = 'w:' + n
        self.link = 0
        self.status = None
        self.nodes[self.wm] = dict(type='window_manager', name='', children=[], visible=1, enable=1)
        self.byte(syms['g_wififlag'], 1)
        self.word(O['NET_TYPE'], 2)

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('w:'):
            return super().hook(u, address, size, unused)
        if name == 'w:write':
            self.calls.append(('write_int_config', *[u.reg_read(r) for r in REGS[:3]]))
            self.returns(0)
            return
        self.calls.append((name[2:], 0, 0, 0))
        status = self.link if self.status is None else self.status
        self.returns(status if name == 'w:networkGetConnectStatus' else 3 if self.link else -1, clobber=True)

    def windows(self, *names):
        self.nodes[self.wm]['children'] = [self.node('window', n) for n in names]
        return self.nodes[self.wm]['children']

    def switch(self):
        return [c[0] for c in self.calls if c[0] in ('networkStart', 'networkStop', 'write_int_config')]

    def flag(self):
        return self.u.mem_read(syms['g_wififlag'], 1)[0]

class SmartMachine(SmartMixin, PowerMachine):

    def __init__(self, smart='1'):
        super().__init__(smart=smart)
        self.mock('system@GLIBC_2.0')
