def wifi_calls(m):
    calls = [(c[0].split('@')[0], c[1]) for c in m.calls]
    keep = lambda c: c[0] in ('networkStop', 'networkStart', 'write_int_config', 'stop_wifisynclink') or (c[0] in ('access', 'remove') and m.text(c[1]) == SW_INIT) or (c[0] == 'memset' and c[1] == syms['wifi_name'])
    return [c if c[0] in ('access', 'remove', 'memset', 'write_int_config') else c[:1] for c in calls if keep(c)]

def wifi_state(m):
    return [m.u.mem_read(a, 1)[0] for a in (syms['g_wififlag'], syms['wifi_connectstatus'], syms['wifi_initstatus'], 10804026, syms['wifilink_timeout'])] + [bytes(m.u.mem_read(syms['wifi_name'], 4))]

def connected(m):
    m.files[SW_INIT] = b''
    m.byte(syms['g_synclinkflag'], 1)
    m.byte(syms['wifi_connectstatus'], 2)
    m.byte(10804026, 5)
    m.byte(syms['wifilink_timeout'], 7)
    m.u.mem_write(syms['wifi_name'], b'Home\x00')
