class SmartBusy(SmartMachine):

    def __init__(self, name, busy):
        super().__init__()
        self.busy = busy
        self.handlers[payload_syms[name]] = 'b:' + name

    def hook(self, u, address, size, unused):
        if self.handlers.get(address, '').startswith('b:'):
            self.returns(self.busy)
            return
        return super().hook(u, address, size, unused)
