class SmartScrobble(SmartMixin, PowerMachine):

    def __init__(self, on=True):
        super().__init__()
        self.mock('system@GLIBC_2.0')
        self.handlers[payload_syms['scrobble_start']] = 's:start'
        self.handlers[payload_syms['scrobble_flag']] = 's:flag'
        self.on = on
        self.starts = 0
        self.flags = 0

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if name == 's:start':
            self.starts += 1
            self.returns(1)
            return
        if name == 's:flag':
            self.flags += 1
            self.returns(int(self.on))
            return
        return super().hook(u, address, size, unused)
