def jpg(w, h, sof=192, bits=8, n=3, pad=0):
    return b'\xff\xd8\xff\xff\xe0\x00\x04ab' + bytes([255, sof]) + struct.pack('>HBHHB', 8 + 3 * n, bits, h, w, n) + bytes(3 * n) + b'\xff\xd9' + bytes(pad)

class LogoMachine(PowerMachine):
    failure = ''

    def __init__(self, files=None):
        super().__init__(files=files)
        self.threads = []
        self.execs = []
        self.toasts = []
        self.rotated = None
        self.child = False
        self.exits = []
        self.handlers[payload_syms['child_exit']] = 'l:exit'
        self.word(10723952, 16777232)
        self.handlers[16777232] = 'l:free'
        for n in ('fseek@GLIBC_2.0', 'ftell@GLIBC_2.0', 'memcmp@GLIBC_2.0', 'strstr@GLIBC_2.0', 'pthread_create@GLIBC_2.2', 'fork@GLIBC_2.0', 'execl@GLIBC_2.0', 'exit@GLIBC_2.0', 'waitpid@GLIBC_2.0', 'open@GLIBC_2.0', 'navigator_to_with_context'):
            self.handlers[syms[n]] = 'l:' + n

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if name.startswith('r:' + self.failure + '@') and (self.failure != 'fopen' or self.text(u.reg_read(REGS[1])) == 'wb'):
            self.returns(0 if self.failure in ('fopen', 'fwrite') else 4294967295)
            return
        if not name.startswith('l:'):
            return super().hook(u, address, size, unused)
        name = name[2:].split('@')[0]
        a, b, c, d = [u.reg_read(r) for r in REGS]
        self.calls.append((name, a, b, c))
        ret = 0
        if name == 'fseek':
            f = self.open[a]
            f[2] = signed(b) + (len(f[3]) if c == 2 else 0)
        elif name == 'ftell':
            ret = self.open[a][2]
        elif name == 'memcmp':
            ret = int(bytes(u.mem_read(a, c)) != bytes(u.mem_read(b, c)))
        elif name == 'strstr':
            i = self.text(a).find(self.text(b))
            ret = a + i if i >= 0 else 0
        elif name == 'pthread_create':
            self.word(a, 77)
            self.threads.append(c)
        elif name == 'open':
            ret = 4294967295
        elif name == 'fork':
            ret = 0 if self.child else 4242
        elif name == 'exit':
            self.exits.append(a)
            for i, r in enumerate(SAVED):
                u.reg_write(r, 305397760 + i)
            u.reg_write(UC_MIPS_REG_SP, 1879109632)
            u.reg_write(UC_MIPS_REG_PC, 16777216)
            return
        elif name == 'execl':
            sp = u.reg_read(UC_MIPS_REG_SP)
            args = [self.text(x) for x in (a, b, c, d)]
            while (x := self.get(sp + 16 + 4 * (len(args) - 4))):
                args.append(self.text(x))
            self.execs.append(args)
        elif name == 'waitpid':
            assert a == 4242
            self.word(b, 0)
            ret = a
            if self.rotated is not None:
                self.files[LOGO_ROT] = self.rotated
        elif name == 'navigator_to_with_context':
            self.toasts.append(self.text(b + 8))
            assert len(self.toasts) < 4, 'a toast that keeps toasting'
            self.nested(sleep_hook, 4660)
        self.returns(ret, clobber=True)

    def sync(self, mounted=True):
        self.files['/proc/mounts'] = b'/dev/mmcblk0p1 /mnt/mmc vfat rw 0 0\n' if mounted else b'none /mnt/data ubifs rw 0 0\n'
        self.threads = []
        self.pass_()
        for t in self.threads:
            self.call(address=t, args=(0, 0, 0, 0), gap=0, clear=False)
        started = len(self.threads)
        self.pass_(1)
        return started
