class HeadsetMachine(Machine):

    def __init__(self, owner=1):
        super().__init__()
        self.owner = owner
        self.playing = True
        self.session = 42
        self.actions = []
        self.saved = 0
        self.handlers[syms['mclGetSavePlayStatus']] = 'hs:saved'
        for name in ('spot_status', 'radio_status', 'video_status', 'spot_session', 'radio_session', 'video_session', 'spot_set_playing', 'radio_set_playing', 'video_set_playing', 'spot_media', 'radio_media', 'video_key'):
            self.handlers[payload_syms[name]] = 'hs:' + name
        self.handlers[syms['mclGetPlayStatus']] = 'hs:local_status'
        self.handlers[syms['player_play_pause']] = 'hs:local_toggle'
        self.handlers[syms['player_next_music']] = 'hs:local_next'
        self.handlers[syms['player_prev_music']] = 'hs:local_prev'

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('hs:'):
            return super().hook(u, address, size, unused)
        name = name[3:]
        a = u.reg_read(REGS[0])
        ret = 0
        owner = 4 if name.startswith('video') else 3 if name.startswith('radio') else 2 if name.startswith('spot') else 1
        if name == 'saved':
            ret = self.saved
        elif name.endswith('_status'):
            ret = (2 if self.playing else 3) if self.owner == owner else 0
        elif name.endswith('_session'):
            ret = self.session
        elif name.endswith('_set_playing'):
            self.playing = bool(a)
            self.actions.append((owner, 'play' if a else 'pause'))
        elif name == 'local_toggle':
            self.playing = not self.playing
            self.actions.append((1, 'play' if self.playing else 'pause'))
        else:
            self.actions.append((owner, a if owner != 1 else name))
            ret = int(name.endswith('_media') and self.owner == owner)
        self.returns(ret)

    def fn(self, name, value=0, gap=0):
        return self.call(address=payload_syms[name], args=(value, 0, 0, 0), gap=gap)

    def ears(self, mask, gap=100):
        return self.fn('headset_ears', 4 | mask, gap)

    def command(self, code, gap=200):
        return self.fn('headset_command', code, gap)
