def hp_keys(key, playing=False, **state):
    m = hp_on(HeadsetMachine(), **state)
    toggle = syms['player_play_pause']
    del m.handlers[toggle]
    m.handlers[toggle + 12] = 'hs:local_toggle'
    m.playing = playing
    m.fn('media_key', O[key])
    return (m.actions, sum((x[0] == 'navigator_to_with_context' for x in m.calls)))
