class InfoMachine(Machine):

    def hook(self, u, address, size, unused):
        if self.handlers.get(address) == 'i:format':
            self.u.mem_write(u.reg_read(UC_MIPS_REG_A1), {'player_location': getattr(self, 'location', b'Location\x00')}.get(self.text(u.reg_read(UC_MIPS_REG_A0)), b'?\x00'))
            self.returns(0)
            return
        return super().hook(u, address, size, unused)
