class GenreMachine(InfoMachine, QueueMachine):
    about = 0

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if name not in ('window_create', 'widget_add_child', 'widget_remove_child'):
            return super().hook(u, address, size, unused)
        a, b = (u.reg_read(REGS[0]), u.reg_read(REGS[1]))
        if name == 'window_create':
            self.about = self.top = self.node('window', 'npabout_page')
            self.stack.append(self.top)
            self.returns(self.about)
            return
        if name == 'widget_remove_child':
            self.nodes[a]['children'].remove(b)
        else:
            self.nodes[a]['children'].append(b)
            self.word(b + O['W_PARENT'], a)
        self.returns(0)
