def genre_page(genre, text_w, about=True):
    m = GenreMachine(queue=3, pos=1)
    m.handlers[syms['getFormatString']] = 'i:format'
    m.handlers[np_page + 12] = 'stock_playing'
    for n in ('window_create', 'widget_add_child', 'widget_remove_child'):
        m.handlers[syms[n]] = n
    source = m.node('label', 'label_genre', text='Genre:' + genre)
    m.word(source + O['W_X'], 75)
    m.word(source + O['W_W'], 225)
    page = m.node('view', 'view_info', [source])
    sv = m.node('slide_view', 'slide_view', value=2)
    win = m.node('window', 'playing_page', [sv, page, m.node('slider', 'slider_play', max=225, value=100)])
    for w, parent in ((source, page), (page, win), (sv, win), (win, m.wm)):
        m.word(w + O['W_PARENT'], parent)
    m.top = win
    m.call(address=np_page, args=(win, 7, 0, 0), gap=0)
    m.timers.clear()
    if about:
        m.call(address=payload_syms['np_about_open'], args=(0, 0, 0, 0), gap=0)
        assert m.about and m.top == m.about and (m.nodes[page].get('visible') == 1)
        m.timers.clear()

    def fill():
        m.call(address=payload_syms['ringnav_np_info'], args=(win, 0, 0, 0), gap=0)
    fill()
    s = next((w for w, n in m.nodes.items() if n.get('name') == 'ringnav_genre_scroll'))
    assert not m.timers and m.get(s + O['HSCROLL_TEXT_W']) == 0
    m.word(s + O['HSCROLL_TEXT_W'], text_w)
    return (m, win, sv, source, s, fill)
