class EqOutputMachine(BtLinkMachine):

    def __init__(self, links=(), way=0, headset=0, po=0, bal=0, on=1):
        super().__init__(links)
        self.way = way
        self.on = on
        self.keys = []
        self.requests = 0
        self.handlers.update({syms['mclGetOutputWay']: 'eo:way', payload_syms['ringnav_eq_output']: 'eo:on', payload_syms['eq_output']: 'eo:key'})
        if 'q2eq_poll' in payload_syms:
            self.handlers[payload_syms['q2eq_poll']] = 'eo:q2eq'
        self.byte(syms['g_headset_output'], headset)
        self.byte(syms['g_po_status'], po)
        self.byte(syms['g_bal_status'], bal)

    def hook(self, u, addr, size, _):
        name = self.handlers.get(addr, '')
        if not name.startswith('eo:'):
            return super().hook(u, addr, size, _)
        if name == 'eo:key':
            self.keys.append(self.text(u.reg_read(REGS[0])))
        if name == 'eo:q2eq':
            self.requests += 1
        self.returns({'eo:way': self.way, 'eo:on': self.on}.get(name, 0))

    def poll(self):
        self.call(address=payload_syms['headset_eq_poll'], args=(0, 0, 0, 0), gap=1000)
        return self.keys
