def sb_machine(content, value, light='1', y=60, table=False, h=96):
    m = Machine()
    m.config['LIGHT'] = light
    if table:
        w, _, _ = m.table_page()
        m.word(w + O['TABLE_ROWS'], content // 48)
    else:
        w, _ = m.page_list(20, height=h, extent=content)
    bar = m.node('scroll_bar_m')
    m.word(bar + O['W_H'], 240)
    m.word(bar + O['BAR_MAX'], max(content, 240))
    m.word(bar + O['BAR_VALUE'], value)
    parent = m.node('list_view' if not table else 'table_view', children=[w, bar])
    m.word(parent + O['W_W'], 240)
    m.word(parent + O['W_H'], h)
    m.word(w + O['W_PARENT'], parent)
    m.word(bar + O['W_PARENT'], parent)
    m.nodes[m.top]['children'] = [parent]
    m.word(m.canvas + O['CANVAS_Y'], y)
    return (m, parent, bar)

def sb_stock(m, bar, name='fg_color'):
    begin(m, bar)
    m.handlers[int(manifest['patch_symbols']['stock_color_trampoline'], 16)] = 'stock_color'
    out = m.alloc(4)
    m.word(out, 4286611584)
    m.call(address=HOOKS['style_get_color'][0], args=(out, 4660, m.string(name), 0), gap=0)
    return m.get(out)

def sb_drawn(m, parent):
    m.bands = []
    m.call(address=HOOKS['widget_on_paint_border'][0], args=(parent, m.canvas, 0, 0), gap=0)
    return [b[:5] for b in m.bands if b[0] >= 229]
