class SwMachine(CoverflowMachine):

    def __init__(self, code=1, quit=0):
        super().__init__()
        oled_set(self)
        self.code, self.quit, self.idles = (code, quit, [])
        self.handlers.pop(HOOKS['fwupdate_tf'][0], None)
        for n in ('check_updatefw_exist', 'navigator_to', 'idle_add'):
            self.handlers[syms[n]] = 'sw:' + n
        self.word(syms['g_power_capacity'], 12)

    def hook(self, u, address, size, unused):
        name = self.handlers.get(address, '')
        if not name.startswith('sw:'):
            return super().hook(u, address, size, unused)
        name = name[3:]
        a, b = [u.reg_read(r) for r in REGS[:2]]
        self.calls.append((name, a, b))
        ret = 0
        if name == 'check_updatefw_exist':
            assert (self.text(a), self.text(b)) == ('/mnt/mmc', '/mnt/mmc/update.tar')
            ret = self.code
        elif name == 'navigator_to':
            self.opened.append((self.text(a),))
            ret = self.quit
        elif name == 'idle_add':
            self.idles.append((a, b))
            ret = 1
        self.returns(ret, clobber=True)

    def sw(self, field):
        return signed(self.get(payload_syms['swu'] + {'state': 4, 'result': 12, 'frame': 24}[field]))

    def said(self, w):
        self.letters.clear()
        self.image_loads.clear()
        self.paint(w, gap=0)
        return ([l['text'] for l in self.letters], [i.rsplit('_', 1)[-1] if 'swspin' not in i else i.split('swspin_')[1] for i in self.image_loads if 'sw' in i])

def sw_open(code=1, quit=0):
    m = SwMachine(code, quit)
    m.call(address=syms['fwupdate_tf'], args=(0, 0, 0, 0), gap=0)
    return m
